  const TOOL_INDEX = {};
  for (const [fam, targets] of Object.entries(TARGETS)) {
    for (const t of targets) {
      if (t.tool) TOOL_INDEX[t.tool] = { family: fam, target: t };
      if (t.inputs && t.inputs.inline) TOOL_INDEX[t.inputs.inline] = { family: fam, target: t };
    }
  }

  function registerPresetAlias(aliasId, fam, targetExtOrTool) {
    const list = TARGETS[fam] || [];
    const t = list.find(x => x.tool === targetExtOrTool || x.ext === targetExtOrTool || (x.inputs && x.inputs.inline === targetExtOrTool) || x.id.includes(targetExtOrTool) || (x.label && x.label.toLowerCase() === targetExtOrTool.toLowerCase()));
    if (t) TOOL_INDEX[aliasId] = { family: fam, target: t };
  }

